function refreshBiomes(){for(const k of Object.keys(biomes))delete biomes[k];Object.assign(biomes,baseBiomes);for(const [id,b] of Object.entries(world.biomes||{}))biomes[id]=[b.name||baseBiomes[id]?.[0]||id,b.color||baseBiomes[id]?.[1]||'#87a982'];for(const b of world.entities||[])if(b.entity_type==='biome'&&b.id)biomes[b.id]=[b.name||biomes[b.id]?.[0]||b.id,b.color||biomes[b.id]?.[1]||'#87a982']}
