 for(const tile of copy.tiles||[])for(const exit of Object.values(tile.exits||{})){
  if(exit.map_id===source.id)exit.map_id=id;
  if(!exit.pair_id)continue;
  if((exit.map_id||id)===id){if(!clonedPairs.has(exit.pair_id))clonedPairs.set(exit.pair_id,newPairId());exit.pair_id=clonedPairs.get(exit.pair_id)}
  else{delete exit.pair_id;delete exit.return_exit}
 }
