  const picker=MudmakerLocationPicker.wire({world,mapSelect,grid,readout,initial:{map_id:initialMap.id,x:Number(row.querySelector('[data-connection-x]').value),y:Number(row.querySelector('[data-connection-y]').value)},onChange:value=>{row.querySelector('[data-connection-map]').value=value.map_id;row.querySelector('[data-connection-x]').value=value.x;row.querySelector('[data-connection-y]').value=value.y;row.dataset.entry='__tile__';fillEntry(row,'__tile__')}});
  row.querySelector('[data-connection-map]').onchange=()=>{fillEntry(row,'',true);const target=world.maps.find(map=>map.id===row.querySelector('[data-connection-map]').value);picker.set({map_id:target.id,x:Number(row.querySelector('[data-connection-x]').value),y:Number(row.querySelector('[data-connection-y]').value)},false)};
  for(const field of ['x','y'])row.querySelector(`[data-connection-${field}]`).addEventListener('input',()=>{row.dataset.entry='__tile__';row.querySelector('[data-connection-entry]').value='__tile__';picker.set({...picker.value,[field]:Number(row.querySelector(`[data-connection-${field}]`).value)},false)});
