let decisionRoutePickerSequence=0;
function decisionRouteRow(route={}){const map=world.maps.find(m=>m.id===(route.map_id||world.default_map_id))||world.maps[0],point=route.location||map.spawn||{x:0,y:0},prefix=`decision-route-picker-${decisionRoutePickerSequence++}`;return `<div class="entity-edit decision-route-row" data-decision-route><div class="form-field"><label>ID</label><input class="input" data-route-id value="${esc(route.id||'destination')}"></div><div class="form-field"><label>NAME</label><input class="input" data-route-name value="${esc(route.name||'Destination')}"></div><div class="form-field"><label>MAP</label><select class="select" data-route-map>${world.maps.map(m=>`<option value="${esc(m.id)}" ${m.id===map.id?'selected':''}>${esc(m.name||m.id)}</option>`).join('')}</select></div><div class="form-field"><label>X</label><input class="input" data-route-x type="number" min="0" max="${map.width-1}" value="${point.x}"></div><div class="form-field"><label>Y</label><input class="input" data-route-y type="number" min="0" max="${map.height-1}" value="${point.y}"></div><details class="form-field full decision-route-picker"><summary>Choose destination on map</summary>${MudmakerLocationPicker.markup({world,mapId:map.id,location:point,prefix,label:'Route destination'})}</details><button class="button button-secondary" data-route-remove type="button" aria-label="Remove destination">×</button></div>`}
function wireDecisionRoutes(){const list=$('#decision-route-list');if(!list)return;const connect=row=>{const mapField=row.querySelector('[data-route-map]'),x=row.querySelector('[data-route-x]'),y=row.querySelector('[data-route-y]'),pickerSelect=row.querySelector('.decision-route-picker [id$="-map"]'),prefix=pickerSelect.id.replace(/-map$/,''),setBounds=()=>{const map=world.maps.find(m=>m.id===mapField.value);x.max=map.width-1;y.max=map.height-1;x.value=Math.max(0,Math.min(+x.value||0,map.width-1));y.value=Math.max(0,Math.min(+y.value||0,map.height-1))};const picker=MudmakerLocationPicker.wire({world,mapSelect:pickerSelect,grid:row.querySelector(`#${prefix}-grid`),readout:row.querySelector(`#${prefix}-readout`),initial:{map_id:mapField.value,x:Number(x.value),y:Number(y.value)},onChange:value=>{mapField.value=value.map_id;x.value=value.x;y.value=value.y;setBounds()}});mapField.onchange=()=>{const map=world.maps.find(m=>m.id===mapField.value);x.value=map.spawn?.x||0;y.value=map.spawn?.y||0;setBounds();picker.set({map_id:map.id,x:Number(x.value),y:Number(y.value)},false)};for(const [field,input] of [['x',x],['y',y]])input.addEventListener('input',()=>picker.set({map_id:mapField.value,...picker.value,[field]:Number(input.value)},false))};$$('[data-decision-route]').forEach(connect);list.onclick=e=>{if(e.target.closest('[data-route-remove]'))e.target.closest('[data-decision-route]').remove()};$('#decision-route-add').onclick=()=>{const map=world.maps.find(m=>m.id===world.default_map_id)||world.maps[0];list.insertAdjacentHTML('beforeend',decisionRouteRow({id:'destination',name:'New destination',map_id:map.id,location:map.spawn||{x:0,y:0}}));connect(list.lastElementChild)}}
function wireDecisionDeliveries(){const add=$('#delivery-task-add');if(!add)return;add.onclick=()=>{try{const tasks=JSON.parse($('#decision-tasks').value||'[]');if(!Array.isArray(tasks))throw Error('Authored tasks must be a JSON array');const name=$('#delivery-task-name').value.trim(),description=$('#delivery-task-description').value.trim(),item=$('#delivery-task-item').value,count=Number($('#delivery-task-count').value),reward=Number($('#delivery-task-reward').value);let id=$('#delivery-task-id').value.trim()||name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!/^[a-z][a-z0-9_-]{0,47}$/.test(id)||tasks.some(task=>task.id===id))throw Error('Use a unique lowercase task id');if(!name||!description||!item||!Number.isInteger(count)||count<1||count>9999||!Number.isInteger(reward)||reward<0)throw Error('Enter a name, description, item, quantity, and nonnegative reward');tasks.push({id,name,description,steps:1,once:true,timeout_seconds:86400,cooldown_seconds:86400,delivery:{item,count},effects:reward?[{type:'currency',amount:reward}]:[]});$('#decision-tasks').value=JSON.stringify(tasks,null,2);$('.decision-action[value="task"]').checked=true;toast('Delivery task added. Save the NPC to keep it.')}catch(error){toast(error.message)}}}
function wireDecisionCommerce(){const host=$('#decision-commerce-items');if(!host)return;const selected=new Set(JSON.parse(host.dataset.selected||'[]'));const draw=()=>{const markets=$$('.decision-market:checked').map(x=>x.value),items=[...new Set((world.economy.vendors||[]).filter(v=>markets.includes(v.id)).flatMap(v=>(v.stock||[]).map(o=>o.item)))];host.innerHTML=`<div class="entity-edit">${items.map(item=>`<label><input type="checkbox" class="decision-commerce-item" value="${esc(item)}" ${selected.has(item)?'checked':''}> ${esc(item)}</label>`).join('')||'<span class="muted">Choose a market with authored offers.</span>'}</div>`};draw();$$('.decision-market').forEach(input=>input.addEventListener('change',()=>{for(const item of $$('.decision-commerce-item:checked'))selected.add(item.value);draw()}))}
function readDecisionPanel(prior){JSON.parse($('#decision-goals').value);const goals=readDecisionGoals();const tasks=$('#decision-tasks')?JSON.parse($('#decision-tasks').value):prior.tasks||[];if(!Array.isArray(tasks))throw Error('Authored tasks must be a JSON array');const commerce=$('#npc-commerce-currency')?{markets:$$('.decision-market:checked').map(x=>x.value),items:$$('.decision-commerce-item:checked').map(x=>x.value),starting_currency:Number($('#npc-commerce-currency').value),starting_inventory:JSON.parse($('#npc-commerce-inventory').value||'{}'),currency_reserve:Number($('#npc-commerce-reserve').value),inventory_capacity:Number($('#npc-commerce-capacity').value),max_units_per_decision:Number($('#npc-commerce-units').value),max_spend_per_decision:Number($('#npc-commerce-spend').value),allow_buy:$('#npc-commerce-buy').value==='true',allow_sell:$('#npc-commerce-sell').value==='true'}:prior.commerce||{};const gathering=$('#npc-gather-units')?{items:$$('.decision-gather-item:checked').map(x=>x.value),max_units_per_decision:Number($('#npc-gather-units').value)}:prior.gathering||{};const crafting=$('#npc-craft-batches')?{recipes:$$('.decision-craft-recipe:checked').map(x=>x.value),max_batches_per_decision:Number($('#npc-craft-batches').value)}:prior.crafting||{};const resources=$('#npc-resource-capacity')?{inventory_capacity:Number($('#npc-resource-capacity').value),starting_inventory:JSON.parse($('#npc-resource-inventory').value||'{}')}:prior.resources||{};const routes=$('#decision-route-list')?$$('[data-decision-route]').map(row=>({id:row.querySelector('[data-route-id]').value.trim(),name:row.querySelector('[data-route-name]').value.trim(),map_id:row.querySelector('[data-route-map]').value,location:{x:Number(row.querySelector('[data-route-x]').value),y:Number(row.querySelector('[data-route-y]').value)}})):prior.routes||[];return {...prior,enabled:$('#decision-enabled').value==='true',provider_id:$('#decision-provider').value,goals,tasks,commerce,gathering,crafting,resources,routes,active_radius:Number($('#decision-radius').value),actions:$$('.decision-action:checked').map(x=>x.value),observations:$$('.decision-observation:checked').map(x=>x.value),triggers:$$('.decision-trigger:checked').map(x=>x.value),fallback:$('#decision-fallback').value,cooldown_seconds:Number($('#decision-cooldown').value),timeout_seconds:Number($('#decision-timeout').value),memory_limit:Number($('#decision-memory').value)}}
function editWorld(){const runtime={ssh_port:2222,mcp_bind:'127.0.0.1',mcp_port:2223,mcp_allowed_hosts:'',...(world.runtime_config||{})};const emotes=world.emotes||[{id:'wave',verb:'wave',broadcast:'waves',icon:'👋'},{id:'cheer',verb:'cheer',broadcast:'cheers',icon:'🎉'},{id:'laugh',verb:'laugh',broadcast:'laughs',icon:'😂'},{id:'shrug',verb:'shrug',broadcast:'shrugs',icon:'🤷'},{id:'dance',verb:'dance',broadcast:'dances',icon:'💃'}];modal(`<div class="modal-head"><div><h2>Realm details</h2><p>Set world content and the runtime options used by exported games.</p></div><button class="modal-close">×</button></div><div class="form-field"><label>WORLD NAME</label><input class="input" id="realm-name" value="${esc(world.name)}"></div><div class="form-field"><label>DESCRIPTION</label><textarea class="textarea" id="realm-desc">${esc(world.description)}</textarea></div><div class="form-field"><label>CURRENCY NAME</label><input class="input" id="realm-currency" value="${esc(world.economy.currency||'Coins')}"></div><h3>Runtime connections</h3><p class="small-copy">Defaults are copied into the exported Compose distribution. The MCP token stays private and is generated by the game at first start. MCP binds to loopback by default; use a protected network path if you change it.</p><div class="entity-edit"><div class="form-field"><label>SSH HOST PORT</label><input class="input" id="runtime-ssh-port" type="number" min="1" max="65535" value="${runtime.ssh_port}"></div><div class="form-field"><label>MCP HOST PORT</label><input class="input" id="runtime-mcp-port" type="number" min="1" max="65535" value="${runtime.mcp_port}"></div><div class="form-field"><label>MCP BIND ADDRESS</label><input class="input" id="runtime-mcp-bind" value="${esc(runtime.mcp_bind)}" placeholder="127.0.0.1"></div><div class="form-field"><label>ALLOWED MCP HOSTS</label><input class="input" id="runtime-mcp-hosts" value="${esc(runtime.mcp_allowed_hosts)}" placeholder="game.home:2223"></div></div><div class="form-field"><label>PLAYER EMOTES (JSON)</label><textarea class="textarea" id="realm-emotes" style="min-height:150px;font:11px 'DM Mono'">${esc(JSON.stringify(emotes,null,2))}</textarea><small class="muted">Each entry has a command id, self verb, broadcast verb, and emoji icon.</small></div><div class="modal-actions"><button class="button button-secondary modal-cancel">Cancel</button><button class="button button-primary" id="realm-save">Save</button></div>`);$('#realm-save').onclick=()=>{try{const nextEmotes=JSON.parse($('#realm-emotes').value);if(!Array.isArray(nextEmotes))throw Error('Emotes must be a JSON array');const sshPort=Number($('#runtime-ssh-port').value),mcpPort=Number($('#runtime-mcp-port').value),bind=$('#runtime-mcp-bind').value.trim(),hosts=$('#runtime-mcp-hosts').value.trim();if(!Number.isInteger(sshPort)||sshPort<1||sshPort>65535||!Number.isInteger(mcpPort)||mcpPort<1||mcpPort>65535)throw Error('Ports must be between 1 and 65535');if(!/^\d{1,3}(?:\.\d{1,3}){3}$/.test(bind))throw Error('MCP bind must be an IPv4 address');if(!/^[A-Za-z0-9.*:, -]*$/.test(hosts))throw Error('Allowed hosts should be comma-separated host names and optional ports');world.name=$('#realm-name').value;world.description=$('#realm-desc').value;world.economy.currency=$('#realm-currency').value;world.emotes=nextEmotes;world.runtime_config={ssh_port:sshPort,mcp_bind:bind,mcp_port:mcpPort,mcp_allowed_hosts:hosts,player_web:runtime.player_web||{enabled:false,port:8080}};save();hideModal();render()}catch(e){toast(`Check realm settings: ${e.message}`)}}}
function modal(html){editorModalContext=null;$('#modal').innerHTML=html;wireEntityFields();wireEntityLocationPicker();wireDecisionRoutes();wireDecisionDeliveries();wireDecisionCommerce();wireDecisionGoals();$('#modal-backdrop').classList.remove('hidden');$$('.modal-close,.modal-cancel').forEach(b=>b.onclick=hideModal);$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')hideModal()}}
