function addKey(){modal(`<div class="modal-head"><div><h2>Invite a player</h2><p>Bind one login name to one public key. Private keys are never needed.</p></div><button class="modal-close">×</button></div><div class="form-field"><label>PLAYER LOGIN NAME</label><input class="input" id="player-name" placeholder="e.g. ariadne" autocomplete="off"></div><div class="form-field"><label>SSH PUBLIC KEY</label><textarea class="textarea" id="public-key" placeholder="ssh-ed25519 AAAA… player@device"></textarea></div><div class="modal-actions"><button class="button button-secondary modal-cancel">Cancel</button><button class="button button-primary" id="key-save">Authorize player</button></div>`);$('#key-save').onclick=()=>{let username=$('#player-name').value.trim(),key=$('#public-key').value.trim();if(!/^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,31}$/.test(username)){toast('Use a 1–32 character login name with letters, numbers, dot, dash, or underscore');return}if(!/^(ssh-ed25519|ssh-rsa|ecdsa-sha2-nistp\d+)\s+[A-Za-z0-9+/]+={0,2}(\s+.*)?$/.test(key)){toast('Paste a valid OpenSSH public key');return}world.ssh_public_keys??=[];if(world.ssh_public_keys.some(p=>p.username.toLowerCase()===username.toLowerCase()||p.public_key===key)){toast('Player name or SSH key is already assigned');return}world.ssh_public_keys.push({username,public_key:key});save();hideModal();render()}}
function openWorkbench(kind='custom_entity',scaffold={},onApply){const parent=onApply&&editorModalContext?.type==='entity'?captureCurrentModalDraft():null;let initial={kind,scaffold,instructions:'',apply:onApply,parent};assistantModal(initial)}
function assistantModal(state){modal(`<div class="modal-head"><div><div class="eyebrow">STORYSMITH · ENTITY WORKBENCH</div><h2>Build from a rough draft</h2><p>Any entity can start with just a name, a sentence, or a partial JSON scaffold.</p></div><button class="modal-close">×</button></div><div class="entity-edit"><div class="form-field"><label>ENTITY TYPE</label><select class="select" id="ai-kind" ${state.apply?'disabled':''}>${['custom_entity','npc','quest','crafting_recipe','vendor','room','item','creature','biome','dialog','description','world'].map(k=>`<option value="${k}" ${state.kind===k?'selected':''}>${k.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="form-field"><label>SHORT CONCEPT (OPTIONAL)</label><input class="input" id="ai-concept" value="${esc(state.concept||'')}" placeholder="e.g. exiled lighthouse keeper"></div><div class="form-field full"><label>PARTIAL SCAFFOLD (JSON)</label><textarea class="textarea" id="ai-scaffold" style="min-height:155px;font:11px 'DM Mono'">${esc(JSON.stringify(state.scaffold||{},null,2))}</textarea></div><div class="form-field full"><label>WHAT SHOULD THE ASSISTANT ADD OR CHANGE?</label><textarea class="textarea" id="ai-instructions" placeholder="Add a secret, a memorable voice, and a quest hook…">${esc(state.instructions||'')}</textarea></div></div><div id="ai-result"></div><div class="modal-actions" style="justify-content:space-between"><span class="muted">Generated content stays a draft until you apply it.</span><div><button class="button button-secondary" id="ai-generate">✳ Generate draft</button> <button class="button button-primary hidden" id="ai-apply">Apply draft</button></div></div>`);editorModalContext={type:'workbench',kind:state.kind,scaffold:structuredClone(state.scaffold||{}),instructions:state.instructions||'',concept:state.concept||'',parent:state.parent||null};$('#ai-generate').onclick=async()=>{const generationButton=$('#ai-generate');try{let scaffold=JSON.parse($('#ai-scaffold').value||'{}');let concept=$('#ai-concept').value.trim();if(concept&&!scaffold.name)scaffold.name=concept;$('#ai-generate').disabled=true;$('#ai-generate').textContent='Generating…';const generatedKind=$('#ai-kind').value;let result=await api(`/api/worlds/${world.id}/generate/${generatedKind}`,{method:'POST',body:{scaffold,instructions:$('#ai-instructions').value}});if(!generationButton.isConnected)return;$('#ai-result').innerHTML=`<div class="form-field"><label>REVIEW AND EDIT GENERATED ENTITY</label><textarea class="textarea" id="ai-output" style="min-height:210px;font:11px 'DM Mono'">${esc(JSON.stringify(result,null,2))}</textarea></div>`;$('#ai-apply').classList.remove('hidden');$('#ai-apply').onclick=()=>{try{let final=JSON.parse($('#ai-output').value);final.entity_type=generatedKind;if(state.apply){hideModal();state.apply(final)}else{if(generatedKind==='world'){for(const k of ['name','description','lore','starting_currency','starting_inventory','emotes','runtime_config'])if(k in final)world[k]=final[k];save();hideModal();render();return}const key={npc:'npcs',quest:'quests',crafting_recipe:'crafting',vendor:'economy'}[generatedKind]||'entities';editEntity(key,null,final)}}catch(e){toast(`Check generated JSON: ${e.message}`)}}}catch(e){toast(e.message)}finally{const button=$('#ai-generate');if(button){button.disabled=false;button.textContent='✳ Generate draft'}}}}
async function loadSettings(){let s=await api('/api/settings');if($('#api-base')){$('#api-base').value=s.base_url;$('#api-model').value=s.model;$('#api-json-mode').checked=s.json_mode==='true';$('#key-status').textContent=s.has_key==='True'?'API key is available in the private workbench environment.':'No API key configured. Local providers can run without one.'}}
async function saveSettings(){try{let v={base_url:$('#api-base').value,model:$('#api-model').value,json_mode:$('#api-json-mode').checked};await api('/api/settings',{method:'PUT',body:v});toast('Endpoint and model saved');loadSettings()}catch(e){toast(e.message)}}
async function exportGame(){try{await flushSave();status('Preparing export…');let r=await fetch(`/api/worlds/${world.id}/export`);if(!r.ok)throw Error((await r.json()).detail);const revision=r.headers.get('X-Mudmaker-World-Revision');let blob=await r.blob();let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${world.id}.zip`;a.click();URL.revokeObjectURL(a.href);status(revision?`Exported revision ${revision.slice(0,12)}`:'All changes saved');toast(revision?`Exported saved revision ${revision.slice(0,12)}`:'Deployable Compose project downloaded')}catch(e){status('Export failed');toast(e.message)}}
function slugName(name){return name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function newScaffold(kind){const obj=structuredClone(templates[kind]||{id:'',name:'',description:''});obj.entity_type=kind;if(obj.location)obj.location={...activeMap().spawn};return obj}
function exportReadinessMarkup(report=lastBuildReport){const current=report?.worldId===world.id?report:null,keys=world.ssh_public_keys||[],providers=world.decision_providers||[],enabledPolicies=[...world.npcs,...(world.economy?.vendors||[])].filter(entity=>entity.decision_policy?.enabled),used=new Set(enabledPolicies.map(entity=>entity.decision_policy.provider_id).filter(Boolean)),bindings=[...new Set(providers.filter(provider=>used.has(provider.id)).map(provider=>provider.endpoint_binding).filter(Boolean))],content=current?.ready?`Ready · revision ${current.revision.slice(0,12)}`:current?`${current.issues.length} issue${current.issues.length===1?'':'s'} · fix validation issues`: 'Run Validate build';return `<section class="panel" id="export-readiness" style="margin-top:14px;padding:14px"><div class="panel-heading"><h3>Export readiness</h3><span class="badge">CHECKLIST</span></div><div class="activity"><div><b>Content</b><small>${esc(content)}</small></div></div><div class="activity"><div><b>Player public keys</b><small>${keys.length?`${keys.length} authorized player${keys.length===1?'':'s'}`:'None · the exported game will reject SSH logins until keys are added.'}</small></div><button class="text-button" data-readiness-go="access">${keys.length?'Review':'Add keys'} →</button></div><div class="activity"><div><b>Runtime settings</b><small>SSH ${world.runtime_config?.ssh_port||2222} · MCP ${world.runtime_config?.mcp_bind||'127.0.0.1'}:${world.runtime_config?.mcp_port||2223}</small></div><button class="text-button" data-readiness-go="customize">Review →</button></div><div class="activity"><div><b>Optional provider bindings</b><small>${bindings.length?`${bindings.length} environment binding${bindings.length===1?'':'s'} included: ${bindings.map(esc).join(', ')}. Set values in the deployment environment.`:'No enabled decision provider bindings.'}</small></div></div><div class="activity"><div><b>Persistent storage</b><small>Keep the exported <code>mud-data</code> Compose volume when updating; it stores player data and the server host key.</small></div></div></section>`}
function playtestView(){const startMap=world.maps.find(map=>map.id===previewStart?.map_id)||world.maps.find(map=>map.id===selectedMapId)||world.maps[0];previewStart||={map_id:startMap.id,...(selectedTile>=0?{x:selectedTile%startMap.width,y:Math.floor(selectedTile/startMap.width)}:(startMap.spawn||{x:0,y:0}))};return `${header('RUNTIME PREVIEW','Playtest your realm','Explore, check quest progress, and try your content with the exported game rules.',`<button class="button button-secondary" id="build-check">Validate build</button>`)}<div class="playtest-layout"><section class="panel"><div class="toolbar-row"><label for="preview-player">Character</label><input class="input" id="preview-player" value="${esc(previewPlayer)}" maxlength="32"><button class="text-button" id="preview-clear">Clear log</button></div>${MudmakerLocationPicker.markup({world,mapId:previewStart.map_id,location:previewStart,prefix:'preview-start',label:'Start / reset preview at'})}<button class=\"button button-secondary\" id=\"preview-reset\">Start fresh here</button><p class=\"small-copy\">Changing the selected location does not move the current character. Start fresh here resets this preview character's progress at the selected tile.</p><pre id=\"preview-log\" class=\"terminal\" aria-live="polite">${esc(previewLines.join('\n'))}</pre><form id="preview-form" class="toolbar-row"><input class="input" id="preview-command" aria-label="Game command" placeholder="Type a command… (↑ / ↓ for history)" autocomplete="off" style="max-width:none"><button class="button button-primary">Run</button></form><div class="quick-commands">${['look','map','journal','quests','inventory','recipes','shop','rest',...(world.emotes||[]).slice(0,3).map(e=>`emote ${e.id}`),'help'].map(command=>`<button class="tool-button" data-preview-command="${command}">${command}</button>`).join('')}</div><p class="small-copy">Preview saves are separate from deployed players. Emotes print here; nearby-player chat and emote broadcasts require a deployed multiplayer session.</p></section><aside class="panel playtest-sidebar"><div class="compass"><button class="button button-secondary north" aria-label="Move north" data-preview-command="north">↑ N</button><button class="button button-secondary west" aria-label="Move west" data-preview-command="west">← W</button><button class="button button-secondary center" data-preview-command="look">⌖</button><button class="button button-secondary east" aria-label="Move east" data-preview-command="east">E →</button><button class="button button-secondary south" aria-label="Move south" data-preview-command="south">S ↓</button></div><div id="preview-dashboard">${previewDashboard()}</div><section class="panel" id="decision-inspector-panel" style="margin-top:14px;padding:14px"><div class="panel-heading"><h3>🧠 Decision inspector</h3><span class="badge">ISOLATED PREVIEW</span></div><p class="small-copy">Preview the exact bounded observation and candidates, then step the configured provider once.</p>${[...world.npcs.filter(n=>n.decision_policy?.enabled).map(n=>({type:"npc",id:n.id,name:n.name})),...(world.economy?.vendors||[]).filter(v=>v.decision_policy?.enabled).map(v=>({type:"market",id:v.id,name:v.name}))].length?`<select class="select" id="decision-preview-owner">${[...world.npcs.filter(n=>n.decision_policy?.enabled).map(n=>({type:"npc",id:n.id,name:n.name})),...(world.economy?.vendors||[]).filter(v=>v.decision_policy?.enabled).map(v=>({type:"market",id:v.id,name:v.name}))].map(o=>`<option value="${o.type}:${esc(o.id)}">${o.type==="market"?"🛒":"🧑"} ${esc(o.name)} · ${o.type}</option>`).join('')}</select><div class="toolbar-row"><button class="button button-secondary" id="decision-preview">Preview</button><button class="button button-primary" id="decision-step">▶ Step decision</button><button class="button button-secondary" id="decision-pause">Ⅱ Pause</button><button class="button button-secondary" id="decision-resume">▶ Resume</button></div>`:'<div class="empty-note">Enable a decision policy on an NPC or market to inspect it here.</div>'}<div id="decision-preview-output" aria-live="polite">No decision preview yet.</div></section>${exportReadinessMarkup()}</aside></div>`}

async function setDecisionPaused(paused){const selected=$('#decision-preview-owner')?.value,host=$('#decision-preview-output');if(!selected||!host)return;const [owner_type,owner_id]=selected.split(':',2);try{await flushSave();const result=await api(`/api/worlds/${world.id}/decision-control`,{method:'POST',body:{player:$('#preview-player')?.value||previewPlayer,owner_type,owner_id,action:paused?'pause':'resume'}});renderDecisionInspector(host,{...result,message:paused?'Controller paused. Manual Step remains available in playtest.':'Controller resumed.'})}catch(error){host.textContent=error.message}}
async function runDecisionControl(step){const host=$('#decision-preview-output'),selected=$('#decision-preview-owner')?.value;if(!host||!selected)return;const [owner_type,owner_id]=selected.split(':',2);try{await flushSave();const worldId=world.id,player=$('#preview-player')?.value||previewPlayer;host.textContent=step?'Waiting for one bounded decision…':'Building decision preview…';const result=await api(`/api/worlds/${worldId}/decision-${step?'step':'preview'}`,{method:'POST',body:{player,owner_type,owner_id}});if(step){if(result.messages?.length)previewLines.push('🧠 '+result.messages.join('\n'));previewLines=previewLines.slice(-150);if($('#preview-log'))$('#preview-log').textContent=previewLines.join('\n');previewState=result.state;if($('#preview-dashboard'))$('#preview-dashboard').innerHTML=previewDashboard()}if(host.isConnected&&$('#decision-preview-owner')?.value===selected)renderDecisionInspector(host,result)}catch(error){host.textContent=error.message}}
async function runPreview(command){
  if(previewBusy)return;
  command=command.trim();if(!command)return;
  previewBusy=true;
  const worldId=world.id,player=$('#preview-player')?.value||previewPlayer;
  $$('[data-preview-command],#preview-form button').forEach(button=>button.disabled=true);
  try{
    await flushSave();
    const result=await api(`/api/worlds/${worldId}/preview`,{method:'POST',body:{player,command,start:previewStart}});
    if(world.id!==worldId)return;
    previewState=result.state;
    previewPlayer=player;
    if(commandHistory.at(-1)!==command)commandHistory.push(command);
    if(commandHistory.length>100)commandHistory.shift();historyCursor=commandHistory.length;
    previewLines.push('> '+command,result.output);previewLines=previewLines.slice(-150);
    if($('#preview-log')){$('#preview-log').textContent=previewLines.join('\n');$('#preview-log').scrollTop=$('#preview-log').scrollHeight;$('#preview-dashboard').innerHTML=previewDashboard();$('#preview-command').focus()}
  }catch(error){toast(error.message)}finally{previewBusy=false;$$('[data-preview-command],#preview-form button').forEach(button=>button.disabled=false)}
}
function renderBuildIssues(report){const panel=$('#build-issues');if(!panel)return;buildIssues=report.issues||[];if(!buildIssues.length){panel.hidden=true;panel.innerHTML='';return}panel.hidden=false;panel.innerHTML=`<div class="panel-heading"><h3>Build validation</h3><span class="badge">${buildIssues.length} issue${buildIssues.length===1?'':'s'} · ${esc((report.revision||'').slice(0,12))}</span></div><div class="list">${buildIssues.map((issue,index)=>`<div class="activity"><div><b>${esc(issue.severity||'error').toUpperCase()}: ${esc(issue.message)}</b><small>${esc(issue.path||'World content')} · revision ${esc((issue.revision||report.revision||'').slice(0,12))}</small></div>${issue.navigation?`<button class="button button-secondary" data-build-issue-open="${index}">Open editor</button>`:''}</div>`).join('')}</div>`}
async function checkBuild(){let saveError=null;try{await flushSave()}catch(error){saveError=error}try{const report=await api(`/api/worlds/${world.id}/validate`,{method:'POST',body:{draft:MudmakerMapState.serialize(world)}});lastBuildReport={...report,worldId:world.id};renderBuildIssues(report);const readiness=$('#export-readiness');if(readiness)readiness.outerHTML=exportReadinessMarkup(lastBuildReport);if(!report.ready){toast(`Build check found ${report.issues.length} issue${report.issues.length===1?'':'s'}`);return}if(saveError)throw saveError;toast(`Build ready: ${report.npcs} NPCs, ${report.quests} quests, ${report.items} items, ${report.biomes} biomes · ${report.revision.slice(0,12)}`)}catch(error){toast(error.message)}}
async function pickWorld(){try{await flushSave();const worlds=await api('/api/worlds');modal(`<div class="modal-head"><div><h2>Your realms</h2><p>Open an existing world or create a new one.</p></div><button class="modal-close">×</button></div><div class="list" style="margin-top:15px">${worlds.map(w=>`<button class="button button-secondary" data-world="${esc(w.id)}">${esc(w.name)} · ${w.width} × ${w.height}</button>`).join('')}</div><div class="toolbar-row" style="margin-top:12px"><input type="file" id="import-world-file" accept="application/json,.json" hidden><button class="button button-secondary" id="import-world-pick">Import world JSON</button><small class="muted">Imports a copy; the selected file stays on your device.</small></div><div class="form-field"><label>NEW REALM NAME</label><input class="input" id="new-realm-name" placeholder="Name your realm"></div><div class="modal-actions"><button class="button button-primary" id="new-realm-create">Create realm</button></div>`);$$('[data-world]').forEach(b=>b.onclick=async()=>{try{world=await api(`/api/worlds/${b.dataset.world}`);ensureMaps();localStorage.setItem('mudmaker-world',world.id);selectedTile=-1;previewLines=[];previewState=null;clearMapHistory();hideModal();go('map');offerRecoveredDraft()}catch(e){toast(e.message)}});$('#import-world-pick').onclick=()=>$('#import-world-file').click();$('#import-world-file').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());const created=await api('/api/worlds/import',{method:'POST',body:{world:imported}});world=await api(`/api/worlds/${created.id}`);ensureMaps();localStorage.setItem('mudmaker-world',world.id);selectedTile=-1;previewLines=[];previewState=null;clearMapHistory();hideModal();go('map');offerRecoveredDraft();toast(`Imported ${world.name}; original file kept on this device`)}catch(error){toast(`Import failed: ${error.message}`)}};$('#new-realm-create').onclick=async()=>{try{const name=$('#new-realm-name').value.trim();if(!name)throw Error('Enter a realm name');world=await api('/api/worlds',{method:'POST',body:{name}});world=await api(`/api/worlds/${world.id}`);ensureMaps();localStorage.setItem('mudmaker-world',world.id);selectedTile=-1;previewLines=[];previewState=null;clearMapHistory();hideModal();go('map');offerRecoveredDraft()}catch(e){toast(e.message)}}}catch(e){toast(e.message)}}
async function boot(){try{const [worlds,schema]=await Promise.all([api('/api/worlds'),api('/api/schema')]);templates=schema.templates;terrainDefinitions=schema.biomes||{};world=worlds.find(w=>w.id===localStorage.getItem('mudmaker-world'))||worlds[0];world=await api(`/api/worlds/${world.id}`);ensureMaps();world.economy??={currency:'Coins',vendors:[]};world.ssh_public_keys??=[];$$('.nav-item').forEach(b=>{b.onclick=()=>go(b.dataset.view);b.setAttribute('aria-label',b.textContent.trim())});$('#world-switch').onclick=pickWorld;$('#open-ai').onclick=()=>go('settings');$('#export-btn').onclick=exportGame;$('#settings-shortcut').onclick=()=>go('settings');go(viewName);offerRecoveredDraft()}catch(e){$('#view').innerHTML=`<section class="panel empty-note">Could not load the workbench: ${esc(e.message)}. Refresh to try again.</section>`}}
boot();
